function Art({category,index=0}:{category:string;index?:number}){return <div className={'art color'+index%3} aria-hidden="true"><span className="pdf-tag">PDF</span><div className="sheet"><div className="sheet-head"><b>RETAIL <em>HUB</em></b><span>DOCUMENTACIÓN DE PROYECTO</span></div><div className="sheet-rule"/>{category==='Planogramas'?<div className="shelves">{[0,1,2].map(i=><div className="shelf" key={i}>{Array.from({length:12},(_,j)=><i key={j} style={{height:16+(j*7+i*3)%16,background:['#1e4c6b','#65b19c','#a2b1b7','#dfbe84'][Math.floor(j/3)%4]}}/>)}</div>)}</div>:<><div className="sheet-title"/><div className="sheet-line"/><div className="sheet-panels">{[0,1].map(i=><div key={i}><div className="diagram"><i/><i/><i/></div><b/>{[0,1,2].map(j=><span key={j}/>)}</div>)}</div></>}<div className="sheet-foot"><span>RETAIL HUB</span><span>01</span></div></div></div>}
export default function Portal(){
 const [userToolsReady,setUserToolsReady]=useState(false);
 const [editStoresReady,setEditStoresReady]=useState(false),[editStoreTarget,setEditStoreTarget]=useState<Store|null>(null);
 const [deleteStoresReady,setDeleteStoresReady]=useState(false),[deleteStoreTarget,setDeleteStoreTarget]=useState<Store|null>(null),[confirmStoreName,setConfirmStoreName]=useState('');
 const [stores,setStores]=useState<Store[]>([]),[activeStore,setActiveStore]=useState<Store|null>(null),[storesLoading,setStoresLoading]=useState(false),[storeSearch,setStoreSearch]=useState(''),[storeName,setStoreName]=useState(''),[assignedStores,setAssignedStores]=useState<string[]>([]);
 const [ready,setReady]=useState(false),[configured,setConfigured]=useState(false),[user,setUser]=useState<User|null>(null),[preview,setPreview]=useState(false),[tab,setTab]=useState('library');
 const [docs,setDocs]=useState<Doc[]>([]),[people,setPeople]=useState<User[]>([]),[connections,setConnections]=useState<any>(null),[search,setSearch]=useState(''),[category,setCategory]=useState('Todos los documentos'),[sort,setSort]=useState('recent'),[view,setView]=useState('grid');
 const [busy,setBusy]=useState(false),[loading,setLoading]=useState(false),[notice,setNotice]=useState(''),[error,setError]=useState(''),[mobile,setMobile]=useState(false),[modal,setModal]=useState<string|null>(null),[selected,setSelected]=useState<Doc|null>(null);
 const [loginName,setLoginName]=useState(''),[password,setPassword]=useState(''),[showPass,setShowPass]=useState(false),[guideStep,setGuideStep]=useState(0),[files,setFiles]=useState<File[]>([]),[uploadCategory,setUploadCategory]=useState('Planogramas'),[progress,setProgress]=useState(0);
 const [newName,setNewName]=useState(''),[newUser,setNewUser]=useState(''),[newPass,setNewPass]=useState(''),[newRole,setNewRole]=useState('reader'),[resetPerson,setResetPerson]=useState<User|null>(null),[resetPass,setResetPass]=useState('');
 const [editPerson,setEditPerson]=useState<User|null>(null),[deletePerson,setDeletePerson]=useState<User|null>(null),[confirmUsername,setConfirmUsername]=useState(''),[showUserPassword,setShowUserPassword]=useState(false);
 const docRequest=useRef(0);
 const input=useRef<HTMLInputElement>(null),frame=useRef<HTMLIFrameElement>(null);
 const toast=(s:string)=>{setNotice(s);setTimeout(()=>setNotice(''),5000);};
 const apiBase=()=>((window as any).RH_CONFIG?.apiBase||'').replace(/\/$/,'');
 const readSession=()=>{try{return JSON.parse(sessionStorage.getItem('rh_session')||'null');}catch{return null;}};
 const saveSession=(d:any)=>{if(d.session)sessionStorage.setItem('rh_session',JSON.stringify(d.session));};
 const refreshing=useRef<Promise<any>|null>(null);
 const renewSession=async()=>{
 if(refreshing.current)return refreshing.current;
 refreshing.current=(async()=>{const session=readSession();if(!session?.refresh_token)throw Error('Inicia sesión para continuar.');
 const r=await fetch(apiBase()+'/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});
 const d=await r.json();if(!r.ok){sessionStorage.removeItem('rh_session');setUser(null);throw Error(d.error||'Vuelve a iniciar sesión.');}saveSession(d);return d;})();
 try{return await refreshing.current;}finally{refreshing.current=null;}
 };
 const api=async(path:string,init:RequestInit={},retry=true):Promise<any>=>{
 const base=apiBase();if(!base){if(path==='status')return {auth:false};throw Error('Falta activar el servidor del portal.');}
 if(path==='refresh')return renewSession();
 const h=new Headers(init.headers);if(typeof init.body==='string'&&!h.has('Content-Type'))h.set('Content-Type','application/json');
 const session=readSession();if(session?.access_token)h.set('Authorization','Bearer '+session.access_token);
 const r=await fetch(base+'/'+path,{...init,headers:h});
 if(r.status===401&&retry&&path!=='login'&&session?.refresh_token){await renewSession();return api(path,init,false);}
 const d:any=r.status===204?{}:await r.json();if(!r.ok)throw Error(d.error||'No se pudo completar la solicitud.');saveSession(d);return d;
 };
 const [fileLink,setFileLink]=useState<{url:string;download:string}|null>(null),[fileError,setFileError]=useState('');
 useEffect(()=>{let active=true;setFileLink(null);setFileError('');if(selected&&!preview){api('documents/'+selected.id+'/link',{method:'POST'}).then(d=>{if(active)setFileLink(d);}).catch(e=>{if(active)setFileError(e.message);});}return()=>{active=false;};},[selected,preview]);
 async function downloadDoc(d:Doc){try{const link=await api('documents/'+d.id+'/link',{method:'POST'});const a=document.createElement('a');a.href=link.download;a.rel='noreferrer';document.body.appendChild(a);a.click();a.remove();}catch(e){setError((e as Error).message);}}
 async function connectDropbox(){setBusy(true);try{const d=await api('dropbox/connect',{method:'POST'});window.location.assign(d.url);}catch(e){setError((e as Error).message);setBusy(false);}}
 async function loadStores(){if(preview){setStores([{id:'example-store',name:'Tienda de ejemplo',enabled:true}]);return;}if(!userToolsReady)return;setStoresLoading(true);try{const d=await api('stores');setStores(d.stores);setActiveStore(current=>current?d.stores.find((v:Store)=>v.id===current.id)||null:null);}catch(e){setError((e as Error).message);}finally{setStoresLoading(false);}}
 async function loadDocs(){const request=++docRequest.current;if(!activeStore){setDocs([]);setLoading(false);return;}setLoading(true);try{const d=await api('documents?store='+encodeURIComponent(activeStore.id));if(request===docRequest.current)setDocs(d.documents);}catch(e){if(request===docRequest.current){setDocs([]);setError((e as Error).message);}}finally{if(request===docRequest.current)setLoading(false);}}
 async function createStore(e:FormEvent){e.preventDefault();if(preview){toast('Vista de diseño: no se creó ninguna tienda.');return;}setBusy(true);setError('');try{const d=await api('stores',{method:'POST',body:JSON.stringify({name:storeName})});setStores(x=>[...x.filter(v=>v.id!==d.store.id),d.store].sort((a,b)=>a.name.localeCompare(b.name,'es')));setActiveStore(d.store);setDocs([]);setModal(null);setStoreName('');toast('Tienda creada. Asigna sus usuarios desde Usuarios.');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function renameStore(e:FormEvent){e.preventDefault();if(!editStoreTarget)return;if(preview){toast('Vista de diseño: no se modificó ninguna tienda.');return;}setBusy(true);setError('');try{
 const d=await api('stores/'+editStoreTarget.id,{method:'PATCH',body:JSON.stringify({name:storeName})});setStores(x=>x.map(v=>v.id===d.store.id?d.store:v).sort((a,b)=>a.name.localeCompare(b.name,'es')));if(activeStore?.id===d.store.id)setActiveStore(d.store);setModal(null);setEditStoreTarget(null);setStoreName('');toast('Nombre de tienda actualizado. Sus permisos se conservan.');
 }catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function removeStore(e:FormEvent){e.preventDefault();if(!deleteStoreTarget)return;if(preview){toast('Vista de diseño: no se eliminó ninguna tienda.');return;}setBusy(true);setError('');try{
 await api('stores/'+deleteStoreTarget.id,{method:'DELETE',body:JSON.stringify({confirm_name:confirmStoreName})});setStores(x=>x.filter(v=>v.id!==deleteStoreTarget.id));if(activeStore?.id===deleteStoreTarget.id){docRequest.current++;setActiveStore(null);setDocs([]);setSelected(null);}setModal(null);setDeleteStoreTarget(null);setConfirmStoreName('');toast('Tienda retirada del portal. Sus archivos se conservan en Dropbox.');
 }catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 function enterStore(store:Store){docRequest.current++;setActiveStore(store);setDocs([]);setSearch('');setCategory('Todos los documentos');setError('');}
 useEffect(()=>{(async()=>{try{const r=await api('status',{},false);setConfigured(r.auth);setDeleteStoresReady(r.features?.deleteStores===true);setEditStoresReady(r.features?.editStores===true);setUserToolsReady(r.version==='2026-10-24-stores');if(r.auth)try{setUser((await api('me')).user);}catch{}}catch{setError('No se pudo consultar el portal. Actualiza la página.');}finally{setReady(true);}})();},[]);
 useEffect(()=>{if(!user)return;if(preview){setStores([{id:'example-store',name:'Tienda de ejemplo',enabled:true}]);setDocs(samples);setPeople([{id:'preview',name:'Víctor',username:'victor',role:'admin',enabled:true}]);return;}if(tab==='library'||tab==='users')loadStores();if(tab==='users')api('users').then(d=>setPeople(d.users)).catch(e=>setError(e.message));if(tab==='connections')api('connections').then(setConnections).catch(e=>setError(e.message));},[user,preview,tab,userToolsReady]);
 useEffect(()=>{if(!user||preview||!userToolsReady||tab!=='library')return;if(activeStore)loadDocs();else{docRequest.current++;setDocs([]);setLoading(false);}},[activeStore?.id,user,preview,userToolsReady,tab]);
 useEffect(()=>{if(!selected&&!modal&&!resetPerson)return;const previous=document.activeElement as HTMLElement|null;const dialog=document.querySelector<HTMLElement>('[role=dialog]');const focusable=()=>Array.from(dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),iframe')||[]).filter(e=>e.offsetParent!==null);focusable()[0]?.focus();const fn=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!busy){setSelected(null);setModal(null);setResetPerson(null);}if(e.key==='Tab'){const items=focusable(),first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};window.addEventListener('keydown',fn);const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{window.removeEventListener('keydown',fn);document.body.style.overflow=old;previous?.focus();};},[selected,modal,resetPerson,busy]);
 useEffect(()=>{if(!user||preview)return;const renew=()=>{api('me').catch(()=>setUser(null));};const timer=setInterval(()=>{api('refresh',{method:'POST'},false).catch(()=>setUser(null));},45*60*1000);const visible=()=>{if(document.visibilityState==='visible')renew();};document.addEventListener('visibilitychange',visible);return()=>{clearInterval(timer);document.removeEventListener('visibilitychange',visible);};},[user,preview]);
 function nav(t:string){setTab(t);setMobile(false);setError('');}
 async function login(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{setUser((await api('login',{method:'POST',body:JSON.stringify({username:loginName,password})},false)).user);setPassword('');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function logout(){if(!preview)try{await api('logout',{method:'POST'});}catch{toast('No se pudo cerrar la sesión. Vuelve a intentar.');return;}sessionStorage.removeItem('rh_session');docRequest.current++;setUser(null);setPreview(false);setDocs([]);setStores([]);setActiveStore(null);setTab('library');setError('');}
 async function sync(){if(preview){toast('Conecta tus cuentas para sincronizar documentos reales.');return;}setBusy(true);setError('');try{let cursor=null,total=0;do{const d=await api('sync',{method:'POST',body:JSON.stringify({cursor})});total+=d.count;cursor=d.cursor;}while(cursor);toast(`${total} documentos revisados en Dropbox.`);await loadStores();await loadDocs();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function toggleDoc(d:Doc){if(preview){toast('Vista de diseño: no se modificó ningún archivo.');return;}try{await api('documents/'+d.id,{method:'PATCH',body:JSON.stringify({published:!d.published})});setDocs(x=>x.map(v=>v.id===d.id?{...v,published:!v.published}:v));toast(d.published?'Documento oculto para los lectores.':'Documento publicado.');}catch(e){setError((e as Error).message);}}
 async function upload(e:FormEvent){e.preventDefault();if(preview){toast('La carga estará disponible al conectar Dropbox y Supabase.');return;}if(!files.length)return;setBusy(true);setError('');setProgress(0);try{let done=0;const total=files.reduce((a,b)=>a+b.size,0);for(const f of files){if(!f.name.toLowerCase().endsWith('.pdf')||!f.size)throw Error('Selecciona PDF que no estén vacíos.');const {ticket}=await api('upload/start',{method:'POST',body:JSON.stringify({filename:f.name,category:uploadCategory,store_id:activeStore?.id})});let offset=0;while(offset<f.size){const part=f.slice(offset,offset+8*1024*1024);await api('upload/chunk',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Upload-Ticket':ticket,'X-Upload-Offset':String(offset)},body:part},false);offset+=part.size;setProgress(Math.round((done+offset)/total*100));}await api('upload/finish',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Upload-Ticket':ticket,'X-Upload-Offset':String(offset)},body:new Uint8Array()},false);done+=f.size;}setModal(null);setFiles([]);toast('Documentos guardados en Dropbox y publicados.');await loadStores();await loadDocs();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function addUser(e:FormEvent){e.preventDefault();if(preview){toast('Conecta Supabase para crear usuarios reales.');return;}setBusy(true);setError('');try{const d=await api('users',{method:'POST',body:JSON.stringify({name:newName,username:newUser,password:newPass,role:newRole,store_ids:assignedStores})});setPeople(p=>[...p,d.user]);setModal(null);setNewName('');setNewUser('');setNewPass('');toast('Usuario creado. Comparte sus datos de forma privada.');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function toggleUser(u:User){if(preview){toast('Vista de diseño: no se cambió ningún acceso.');return;}try{const d=await api('users/'+u.id,{method:'PATCH',body:JSON.stringify({enabled:!u.enabled})});setPeople(p=>p.map(x=>x.id===u.id?d.user:x));toast(u.enabled?'Acceso desactivado.':'Acceso activado.');}catch(e){setError((e as Error).message);}}
 async function reset(e:FormEvent){e.preventDefault();if(preview){toast('Las contraseñas se gestionarán al activar Supabase.');return;}setBusy(true);setError('');try{await api('users/'+resetPerson!.id,{method:'PATCH',body:JSON.stringify({password:resetPass})});setResetPerson(null);setResetPass('');toast('Contraseña actualizada.');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 function openEdit(u:User){setEditPerson(u);setNewName(u.name||'');setNewUser(u.username);setNewRole(u.role);setAssignedStores((u.store_ids||[]).filter(id=>stores.some(v=>v.id===id&&v.enabled)));setShowUserPassword(false);setError('');setModal('edit');}
 async function editUser(e:FormEvent){e.preventDefault();if(!editPerson)return;if(preview){toast('Vista de diseño: no se modificó ningún usuario.');return;}setBusy(true);setError('');try{
 const d=await api('users/'+editPerson.id,{method:'PATCH',body:JSON.stringify({name:newName,username:newUser,role:newRole,store_ids:assignedStores})});
 setPeople(p=>p.map(u=>u.id===editPerson.id?d.user:u));if(editPerson.id===user?.id)setUser(d.user);setModal(null);setEditPerson(null);toast('Datos del usuario actualizados.');
 }catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function deleteUser(e:FormEvent){e.preventDefault();if(!deletePerson)return;if(preview){toast('Vista de diseño: no se eliminó ningún usuario.');return;}setBusy(true);setError('');try{
 await api('users/'+deletePerson.id,{method:'DELETE',body:JSON.stringify({confirm_username:confirmUsername})});setPeople(p=>p.filter(u=>u.id!==deletePerson.id));setModal(null);setDeletePerson(null);setConfirmUsername('');toast('Usuario eliminado.');
 }catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 const categories=['Todos los documentos',...Array.from(new Set(docs.map(d=>d.category)))];
 const filtered=docs.filter(d=>(category==='Todos los documentos'||d.category===category)&&`${d.title} ${d.filename} ${d.category}`.toLocaleLowerCase('es').includes(search.toLocaleLowerCase('es'))).sort((a,b)=>sort==='name'?a.title.localeCompare(b.title,'es'):new Date(b.modified_at).getTime()-new Date(a.modified_at).getTime());
 const admin=user?.role==='admin';
 const storeChoices=<fieldset className="store-choices"><legend>Tiendas autorizadas</legend>{newRole==='admin'?<p>Los administradores tienen acceso a todas las tiendas.</p>:<>{stores.filter(v=>v.enabled).length?stores.filter(v=>v.enabled).map(store=><label className="store-choice" key={store.id}><input type="checkbox" checked={assignedStores.includes(store.id)} onChange={e=>setAssignedStores(ids=>e.target.checked?[...ids,store.id]:ids.filter(id=>id!==store.id))}/><span>{store.name}</span></label>):<p>Primero crea una tienda o sincroniza sus carpetas de Dropbox.</p>}<p>Sin tiendas seleccionadas, este usuario no verá documentos.</p></>}</fieldset>;
 const storeHome=<section className="store-home"><div className="section-title"><h2>Selecciona una tienda</h2>{admin&&<button className="text-link" disabled={busy||(!preview&&!userToolsReady)} onClick={sync}><RefreshCw size={15} className={busy?'spin':''}/>Sincronizar Dropbox</button>}</div><div className="search-field"><Search size={18}/><input aria-label="Buscar tienda" placeholder="Buscar una tienda…" value={storeSearch} onChange={e=>setStoreSearch(e.target.value)}/></div>{!preview&&!userToolsReady?<div className="soft-note"><Settings size={20}/>Falta aplicar la actualización de tiendas y permisos. La biblioteca estará disponible al completar la actualización.</div>:storesLoading?<div className="empty-state"><LoaderCircle className="spin"/><h3>Cargando tiendas…</h3></div>:stores.length?<div className="stores-grid">{stores.filter(v=>v.name.toLocaleLowerCase('es').includes(storeSearch.toLocaleLowerCase('es'))).map(store=><article className="store-card" key={store.id}><button className="store-open" onClick={()=>enterStore(store)}><span className="store-card-icon"><FolderOpen size={30}/></span><h2>{store.name}</h2><p>{admin?'Administrar documentos':'Consultar documentos'}</p><span className="text-link">Abrir tienda <ArrowRight size={16}/></span></button>{admin&&<div className="store-card-actions"><button className="text-link" disabled={busy||(!preview&&!editStoresReady)} title={editStoresReady?'Editar nombre de tienda':'Falta aplicar la actualización de la función'} onClick={()=>{setEditStoreTarget(store);setStoreName(store.name);setError('');setModal('edit-store');}}><Pencil size={15}/>Editar</button><button className="text-link store-delete-link" disabled={busy||(!preview&&!deleteStoresReady)} title={deleteStoresReady?'Eliminar tienda del portal':'Falta aplicar la actualización de la función'} onClick={()=>{setDeleteStoreTarget(store);setConfirmStoreName('');setError('');setModal('delete-store');}}><Trash2 size={15}/>Eliminar del portal</button></div>}</article>)}</div>:<div className="empty-state"><FolderOpen size={32}/><h3>{admin?'Crea tu primera tienda':'Aún no tienes tiendas asignadas'}</h3><p>{admin?'Crea una tienda aquí o sincroniza las carpetas que ya preparaste en Dropbox.':'El administrador debe autorizarte el acceso a una tienda para consultar sus documentos.'}</p></div>}<div className="soft-note"><ShieldCheck size={20}/>{admin?'Cada carpeta es una tienda. Asigna a cada usuario sus tiendas desde Usuarios.':'Aquí aparecen únicamente las tiendas que tienes autorizadas.'}</div></section>;
 const Guide=()=> <div className="guide"><div className="eyebrow">ACTIVACIÓN DEL PORTAL</div><h2>Conectemos lo que ya tienes.</h2><p>Para usar documentos y usuarios reales faltan las conexiones de tus cuentas.</p><div className="guide-tabs">{['Supabase','Dropbox','Primer acceso'].map((x,i)=><button className={guideStep===i?'active':''} key={x} onClick={()=>setGuideStep(i)}>{i+1}. {x}</button>)}</div>{guideStep===0?<><h3>Usuarios y catálogo</h3><ol><li>Crea un proyecto de Supabase dedicado al portal.</li><li>Ejecuta <code>database/setup.sql</code>, incluido en el código del proyecto.</li><li>Desactiva el registro público en Authentication → Sign In / Providers.</li><li>Despliega la función <code>retailhub-api</code> en Edge Functions. Supabase proporciona sus claves al servidor.</li></ol><a className="text-link" href="https://supabase.com/dashboard" target="_blank" rel="noreferrer">Abrir Supabase <ArrowUpRight size={15}/></a></>:guideStep===1?<><h3>Tu carpeta de documentos</h3><ol><li>Crea una aplicación en Dropbox con acceso «App folder», para mantener sus archivos separados del resto de tu cuenta.</li><li>Activa <code>files.metadata.read</code>, <code>files.content.read</code> y <code>files.content.write</code>.</li><li>Guarda <code>DROPBOX_APP_KEY</code> y <code>DROPBOX_APP_SECRET</code> en Edge Functions → Secrets.</li><li>Configura la URL de redirección del servidor: <code>La dirección se definirá al activar el servidor; no uses aquí GitHub Pages.</code>.</li><li>Dentro de la carpeta de la aplicación crea <b>Retail Hub/Portal</b>. Dentro crea una carpeta por tienda y coloca sus PDF ahí; las subcarpetas de cada tienda serán categorías. Luego pulsa «Conectar Dropbox» y «Sincronizar».</li></ol><a className="text-link" href="https://www.dropbox.com/developers/apps" target="_blank" rel="noreferrer">Abrir aplicaciones de Dropbox <ArrowUpRight size={15}/></a></>:<><h3>Tu acceso como administrador</h3><ol><li>En Supabase → Authentication → Users crea <code>victor@usuarios.retailhub.invalid</code> con tu contraseña y activa «Auto Confirm User».</li><li>Ejecuta la sentencia del primer administrador al final de <code>database/setup.sql</code>.</li><li>Entra con el usuario <b>victor</b>. Desde Usuarios podrás crear los demás accesos sin pedirles correo.</li><li>El portal estará en GitHub Pages. Los documentos se habilitarán después de conectar el servidor y probar el acceso con usuario y contraseña.</li></ol><div className="soft-note"><ShieldCheck size={20}/>Las claves de Dropbox y Supabase permanecen en el servidor.</div></>}</div>;
 if(!ready)return <div className="loading-screen"><img src="/RetailHub/BibliotecaPlanog/assets/retail-hub.png" alt="Retail Hub"/><LoaderCircle className="spin"/></div>;
 if(!user)return <div className="login-page"><section className="login-story"><img className="login-brand" src="/RetailHub/BibliotecaPlanog/assets/retail-hub.png" alt="Retail Hub"/><div className="story-content"><div className="eyebrow light"><span/>BIBLIOTECA DE PROYECTOS</div><h1>Todo lo que necesitas.<br/><span>En el mismo lugar.</span></h1><div className="story-art"><Art category="Planogramas"/><div className="floating-label"><CheckCircle2 size={20}/><div><b>Del diseño a la ejecución</b><span>Información lista para tu equipo</span></div></div></div></div><div className="story-foot">DOCUMENTACIÓN QUE CONECTA A TU EQUIPO<span>RETAIL HUB © 2026</span></div></section><section className="login-form-side"><div className="login-form-wrap"><span className="lock-circle"><LockKeyhole size={23}/></span><div className="eyebrow">ACCESO AUTORIZADO</div><h2>Bienvenido de vuelta.</h2><p>Ingresa con el usuario y contraseña que te proporcionó el administrador.</p><form onSubmit={login}><label>Usuario<input autoComplete="username" placeholder="Tu nombre de usuario" value={loginName} onChange={e=>setLoginName(e.target.value)} required/></label><label>Contraseña<div className="password-wrap"><input type={showPass?'text':'password'} autoComplete="current-password" placeholder="Ingresa tu contraseña" value={password} onChange={e=>setPassword(e.target.value)} required/><button type="button" aria-label="Mostrar u ocultar contraseña" onClick={()=>setShowPass(!showPass)}><Eye size={18}/></button></div></label>{error&&<div className="inline-error" role="alert">{error}</div>}{!configured&&<div className="setup-note"><span className="dot amber"/>Portal en preparación. Falta conectar tus cuentas.</div>}<button className="primary login-submit" disabled={busy||!configured}>{busy?<LoaderCircle size={18} className="spin"/>:<>Ingresar al portal<ArrowRight size={18}/></>}</button></form><div className="login-help">¿Necesitas acceso? Contacta al administrador de Retail Hub.</div>{!configured&&<div className="preview-actions"><button className="text-link" onClick={()=>{setPreview(true);setUser({id:'preview',name:'Víctor',username:'victor',role:'admin',enabled:true});setError('');}}>Explorar el diseño del portal <ArrowRight size={16}/></button><button className="text-link muted" onClick={()=>setModal('guide')}>Cómo activar las conexiones</button></div>}<div className="login-privacy"><ShieldCheck size={15}/>Acceso privado · Documentos de Retail Hub</div></div></section>{modal==='guide'&&<div className="overlay" onClick={()=>setModal(null)}><section role="dialog" aria-modal="true" aria-label="Activación del portal" className="modal guide-modal" onClick={e=>e.stopPropagation()}><button className="close" aria-label="Cerrar" onClick={()=>setModal(null)}><X/></button><Guide/></section></div>}</div>;
 return <div className="app-shell"><aside className={'sidebar '+(mobile?'open':'')}><a className="brand" href="/" onClick={e=>{e.preventDefault();nav('library');}}><img src="/RetailHub/BibliotecaPlanog/assets/retail-hub.png" alt="Retail Hub"/></a><div className="workspace-label">ESPACIO DE TRABAJO</div><nav><button className={'nav-item '+(tab==='library'?'active':'')} onClick={()=>nav('library')}><BookOpen size={19}/>Biblioteca<ChevronRight className="nav-chevron" size={15}/></button>{admin&&<><div className="workspace-label admin-label">ADMINISTRACIÓN</div><button className={'nav-item '+(tab==='users'?'active':'')} onClick={()=>nav('users')}><Users size={19}/>Usuarios</button><button className={'nav-item '+(tab==='connections'?'active':'')} onClick={()=>nav('connections')}><Settings size={19}/>Conexiones</button></>}</nav><div className="sidebar-bottom"><div className="private-card"><ShieldCheck size={23}/><b>Un espacio de confianza</b><p>Documentos disponibles solo para tu equipo autorizado.</p></div><button className="profile" onClick={logout} title="Cerrar sesión"><span className="avatar">{user.name?.slice(0,1).toUpperCase()}</span><span><b>{user.name}</b><small>{admin?'Administrador':'Usuario autorizado'}</small></span><LogOut size={17}/></button></div></aside>{mobile&&<button className="scrim" aria-label="Cerrar menú" onClick={()=>setMobile(false)}/>}
 <div className="main-shell"><header className="topbar"><div className="breadcrumbs"><button className="mobile-menu icon-btn" aria-label="Abrir menú" onClick={()=>setMobile(!mobile)}><Menu size={21}/></button><span>Retail Hub</span><ChevronRight size={14}/><b>{tab==='library'?'Biblioteca':tab==='users'?'Usuarios':'Conexiones'}</b></div><div className="topbar-right">{preview?<span className="preview-badge">Vista de diseño</span>:<span className="private-badge"><LockKeyhole size={13}/>Acceso privado</span>}<span className="mini-avatar">{user.name?.slice(0,1).toUpperCase()}</span></div></header>{preview&&<div className="preview-banner"><span><AlertCircle size={15}/><b>Vista de diseño.</b> Documentos de ejemplo; conexiones pendientes.</span><button onClick={()=>nav('connections')}>Activar portal <ArrowRight size={14}/></button></div>}
 <main><div className="page-heading"><div><div className="eyebrow">{tab==='library'?'EL CONOCIMIENTO DE CADA PROYECTO':tab==='users'?'TU EQUIPO, CONECTADO':'TODO EN SU LUGAR'}</div><h1>{tab==='library'?(activeStore?activeStore.name:'Tiendas y documentos'):tab==='users'?'Usuarios y accesos':'Conexiones del portal'}</h1><p>{tab==='library'?(activeStore?'Consulta los documentos de esta tienda.':'Selecciona una tienda para consultar sus documentos.'):tab==='users'?'Tú decides quién puede consultar la documentación de Retail Hub.':'Aprovecha tu Dropbox y mantén el control de tus documentos.'}</p></div>{admin&&tab==='library'&&!activeStore&&<button className="primary" disabled={!preview&&!userToolsReady} onClick={()=>{setStoreName('');setError('');setModal('store');}}><Plus size={18}/>Crear tienda</button>}{admin&&tab==='library'&&activeStore&&<button className="primary" onClick={()=>{setFiles([]);setModal('upload');setError('');}}><Plus size={18}/>Subir documentos</button>}{tab==='users'&&<button disabled={!preview&&!userToolsReady} className="primary" onClick={()=>{setModal('user');setNewName('');setNewUser('');setNewPass('');setNewRole('reader');setAssignedStores([]);setShowUserPassword(false);setError('');}}><Plus size={18}/>Crear usuario</button>}</div>{error&&<div className="error-banner" role="alert"><AlertCircle size={18}/>{error}<button aria-label="Cerrar aviso" onClick={()=>setError('')}><X size={17}/></button></div>}
 {tab==='library'?<>{!activeStore?storeHome:<><button className="text-link store-back" onClick={()=>{docRequest.current++;setActiveStore(null);setDocs([]);setSearch('');setCategory('Todos los documentos');}}><FolderOpen size={16}/>Volver a tiendas</button><section className="library-hero"><div className="hero-copy"><div className="hero-label"><span/>BIBLIOTECA RETAIL HUB</div><h2>Un buen proyecto empieza<br/>con la información correcta.</h2><p>Tu documentación de trabajo, organizada y a la mano.</p><div className="hero-pills"><span><Eye size={14}/>Visualiza</span><span><Printer size={14}/>Imprime</span><span><Download size={14}/>Descarga</span></div></div><div className="hero-art"><Art category="Planogramas"/><span><Check size={25}/></span></div></section><section className="stats"><div><span className="stat-icon blue"><FileText size={20}/></span><span><b>{String(docs.filter(d=>d.published).length).padStart(2,'0')}</b><small>{preview?'Documentos de ejemplo':'Documentos publicados'}</small></span></div><div><span className="stat-icon green"><FolderOpen size={20}/></span><span><b>{String(categories.length-1).padStart(2,'0')}</b><small>Categorías disponibles</small></span></div><div><span className="stat-icon pale"><Cloud size={22}/></span><span><b className="stat-word">Dropbox</b><small>{preview?'Conexión por activar':'Archivos en tu almacenamiento'}</small></span><span className={'dot '+(preview?'amber':'')}/></div></section><section className="document-section"><div className="section-title"><h2>Explora la biblioteca <span>{docs.length}</span></h2>{admin&&<button className="text-link muted" disabled={busy} onClick={sync}><RefreshCw size={14} className={busy?'spin':''}/>{busy?'Sincronizando…':'Sincronizar Dropbox'}</button>}</div><div className="filters"><div className="search-field"><Search size={18}/><input aria-label="Buscar documentos" placeholder="Buscar por nombre, categoría o archivo…" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button aria-label="Limpiar búsqueda" onClick={()=>setSearch('')}><X size={15}/></button>}</div><div className="filter-actions"><select aria-label="Ordenar documentos" value={sort} onChange={e=>setSort(e.target.value)}><option value="recent">Más recientes</option><option value="name">Nombre: A–Z</option></select><div className="view-toggle"><button aria-label="Vista de tarjetas" className={view==='grid'?'active':''} onClick={()=>setView('grid')}><Grid2X2 size={17}/></button><button aria-label="Vista de lista" className={view==='list'?'active':''} onClick={()=>setView('list')}><List size={18}/></button></div></div></div><div className="category-tabs">{categories.map(c=><button className={category===c?'active':''} onClick={()=>setCategory(c)} key={c}>{c}</button>)}</div>{loading?<div className="empty-state"><LoaderCircle className="spin" size={28}/><h3>Cargando biblioteca…</h3></div>:filtered.length?<div className={'docs '+view}>{filtered.map((d,i)=><article className={'doc-card '+(!d.published?'unpublished':'')} key={d.id}><button className="art-button" onClick={()=>setSelected(d)} aria-label={'Ver '+d.title}><Art category={d.category} index={i}/></button><div className="doc-body"><div className="doc-category"><span>{d.category}</span><small>{preview?'EJEMPLO':'PDF'}</small></div><button className="doc-title" onClick={()=>setSelected(d)}>{d.title}</button><div className="doc-meta"><span>{size(d.size)}</span><i/>{date(d.modified_at)}{!d.published&&<span>· Oculto</span>}</div><div className="doc-actions"><button onClick={()=>setSelected(d)}><Eye size={15}/>Visualizar</button><div>{admin&&<button className="icon-btn visibility" title={d.published?'Ocultar para lectores':'Publicar documento'} aria-label={d.published?'Ocultar '+d.title:'Publicar '+d.title} onClick={()=>toggleDoc(d)}>{d.published?<CheckCircle2 size={16}/>:<Plus size={16}/>}</button>}<button className="icon-btn" aria-label={'Imprimir '+d.title} title="Abrir para imprimir" onClick={()=>setSelected(d)}><Printer size={16}/></button>{preview?<button className="icon-btn" aria-label={'Descargar '+d.title} title="Descargar" onClick={()=>toast('Conecta Dropbox para descargar los documentos reales.')}><Download size={16}/></button>:<button className="icon-btn" aria-label={'Descargar '+d.title} title="Descargar" onClick={()=>downloadDoc(d)}><Download size={16}/></button>}</div></div></div></article>)}</div>:<div className="empty-state"><FolderOpen size={32}/><h3>{docs.length?'No encontramos coincidencias':'Tu biblioteca está lista para recibir documentos'}</h3><p>{docs.length?'Prueba con otro nombre o categoría.':admin?'Sube un PDF o sincroniza la carpeta de Dropbox.':'Los documentos aparecerán cuando el administrador los publique.'}</p>{docs.length>0&&<button className="secondary" onClick={()=>{setSearch('');setCategory('Todos los documentos');}}>Limpiar filtros</button>}</div>}<div className="library-foot"><ShieldCheck size={15}/>Documentación para usuarios autorizados de Retail Hub.<span>{filtered.length} documentos</span></div></section></>}</>:tab==='users'?<section className="panel"><div className="panel-heading"><div><h2>Personas con acceso</h2><p>Cada lector puede consultar, imprimir y descargar los documentos de las tiendas que le asignes.</p></div><Users size={22}/></div>{!preview&&!userToolsReady&&<div className="soft-note"><Settings size={20}/>Falta aplicar la actualización del servidor para habilitar las tiendas y la administración de usuarios.</div>}<div className="table-scroll"><table><thead><tr><th>Persona</th><th>Usuario</th><th>Permisos</th><th>Tiendas</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{people.map(u=><tr key={u.id}><td><div className="person"><span className="avatar">{u.name?.slice(0,1)}</span><b>{u.name}</b></div></td><td>{u.username}</td><td>{u.role==='admin'?'Administrador':'Consulta y descarga'}</td><td title={stores.filter(v=>u.store_ids?.includes(v.id)).map(v=>v.name).join(', ')}>{u.role==='admin'?'Todas':stores.some(v=>u.store_ids?.includes(v.id))?`${stores.filter(v=>u.store_ids?.includes(v.id)).length} asignadas`:'Sin acceso a tiendas'}</td><td><span className={'user-status '+(!u.enabled?'off':'')}><i/>{u.enabled?'Activo':'Desactivado'}</span></td><td><div className="table-actions"><button className="icon-btn" disabled={busy||(!preview&&!userToolsReady)} aria-label={"Editar a "+u.name} title="Editar usuario" onClick={()=>openEdit(u)}><Pencil size={17}/></button><button className="icon-btn" aria-label={'Cambiar contraseña de '+u.name} title="Cambiar contraseña" onClick={()=>{setResetPerson(u);setResetPass('');setShowUserPassword(false);setError('');}}><KeyRound size={17}/></button><button className="secondary small" disabled={busy||u.id===user.id} onClick={()=>toggleUser(u)}>{u.enabled?'Desactivar':'Activar'}</button><button className="icon-btn danger-icon" disabled={busy||u.id===user.id||(!preview&&!userToolsReady)} aria-label={"Eliminar a "+u.name} title={u.id===user.id?'No puedes eliminar tu propio acceso':'Eliminar usuario'} onClick={()=>{setDeletePerson(u);setConfirmUsername('');setError('');setModal('delete');}}><Trash2 size={17}/></button></div></td></tr>)}</tbody></table></div><div className="soft-note"><ShieldCheck size={20}/>No hay registro público. Solo los administradores pueden crear accesos.</div></section>:<><div className="connection-grid"><section className="connection-card"><span className="connection-icon green"><ShieldCheck size={25}/></span><span className={'connection-state '+(!connections?.auth?'pending':'')}>{connections?.auth?'Configurado':'Por conectar'}</span><h2>Usuarios y catálogo</h2><p>Supabase administra los accesos y la información de tus documentos. Los PDF permanecen en Dropbox.</p><ul><li><Check size={15}/>Usuario y contraseña asignados</li><li><Check size={15}/>Acceso de lectura o administrador</li><li><Check size={15}/>Catálogo protegido en el servidor</li></ul><button className="secondary" onClick={()=>{setGuideStep(0);setModal('guide');}}>Ver configuración <ArrowUpRight size={16}/></button></section><section className="connection-card"><span className="connection-icon blue"><Cloud size={27}/></span><span className={'connection-state '+(!connections?.dropbox?'pending':'')}>{connections?.dropbox?'Autorizado':'Por conectar'}</span><h2>Tu Dropbox</h2><p>Aprovecha el almacenamiento que ya pagas. Solo se publican los PDF de la carpeta elegida para el portal.</p><div className="folder-path"><FolderOpen size={17}/>{connections?.root||'/Retail Hub/Portal'}</div><p className="tiny">Cada carpeta dentro de Portal representa una tienda. Dentro de cada tienda puedes usar subcarpetas como categorías. Sincroniza después de añadir o reemplazar documentos.</p><div className="connection-buttons">{!preview&&connections?.dropboxApp?<button className="primary" disabled={busy} onClick={connectDropbox}><Link2 size={16}/>{connections.dropbox?'Volver a autorizar':'Conectar Dropbox'}</button>:<button className="primary" onClick={()=>{setGuideStep(1);setModal('guide');}}><Link2 size={16}/>Configurar Dropbox</button>}<button className="secondary" disabled={busy} onClick={sync}><RefreshCw size={16} className={busy?'spin':''}/>Sincronizar</button></div></section></div><section className="activation-strip"><span>01</span><div><h3>{connections?.database&&connections?.dropbox?'Tus cuentas están conectadas.':'Activemos tus cuentas paso a paso.'}</h3><p>{connections?.database&&connections?.dropbox?'Administra los accesos desde Usuarios y sincroniza después de cambiar archivos en Dropbox.':'Completa las conexiones para usar documentos reales.'}</p></div><button className="text-link" onClick={()=>setModal('guide')}>Guía de activación<ArrowRight size={17}/></button></section></>}
 <footer className="main-footer"><span>RETAIL HUB · Biblioteca de proyectos</span><span>Del plano a la tienda.</span></footer></main></div>
 {notice&&<div className="toast" role="status"><CheckCircle2 size={18}/>{notice}<button aria-label="Cerrar aviso" onClick={()=>setNotice('')}><X size={16}/></button></div>}
 {(modal||selected||resetPerson)&&<div className="overlay" onClick={()=>{if(!busy){setModal(null);setSelected(null);setResetPerson(null);}}}><section role="dialog" aria-modal="true" aria-label={selected?selected.title:resetPerson?'Cambiar contraseña':modal==='upload'?'Subir documentos':modal==='user'?'Crear usuario':modal==='edit'?'Editar usuario':modal==='delete'?'Eliminar usuario':modal==='store'?'Crear tienda':modal==='delete-store'?'Eliminar tienda del portal':modal==='edit-store'?'Editar tienda':'Activación del portal'} className={'modal '+(selected?'viewer-modal':modal==='guide'?'guide-modal':'')} onClick={e=>e.stopPropagation()}><button className="close" disabled={busy} aria-label="Cerrar" onClick={()=>{setModal(null);setSelected(null);setResetPerson(null);}}><X size={21}/></button>{selected?<><div className="viewer-heading"><span className="stat-icon blue"><FileText size={22}/></span><div><small>{selected.category}</small><h2>{selected.title}</h2></div></div><div className="viewer-toolbar"><span>{size(selected.size)} · {date(selected.modified_at)}</span><div>{!preview&&<><button className="secondary small" disabled={!fileLink} onClick={()=>{if(!fileLink)return;try{frame.current?.contentWindow?.print();}catch{window.open(fileLink.url,'_blank','noopener,noreferrer');}}}><Printer size={16}/>Imprimir</button><button className="primary small" onClick={()=>downloadDoc(selected)}><Download size={16}/>Descargar PDF</button></>}</div></div>{preview?<div className="viewer-example"><Art category={selected.category}/><h3>Documento de ejemplo</h3><p>Al conectar Dropbox podrás abrir aquí el PDF completo, imprimirlo y descargarlo.</p><button className="primary" onClick={()=>{setSelected(null);nav('connections');}}>Ver conexiones<ArrowRight size={16}/></button></div>:fileLink?<iframe ref={frame} title={selected.title} src={fileLink.url} referrerPolicy="no-referrer" className="pdf-frame"/>:<div className="viewer-example">{fileError?<p role="alert">{fileError}</p>:<><LoaderCircle className="spin"/><p>Abriendo documento…</p></>}</div>}</>:modal==='guide'?<Guide/>:modal==='edit-store'&&editStoreTarget?<><span className="modal-icon"><Pencil/></span><h2>Editar tienda</h2><p>Actualiza el nombre de <b>{editStoreTarget.name}</b> en el portal y en Dropbox.</p><form onSubmit={renameStore}><label>Nombre de la tienda<input required maxLength={100} value={storeName} onChange={e=>setStoreName(e.target.value)}/></label><div className="soft-note"><ShieldCheck size={19}/>Sus documentos y los usuarios autorizados se conservan.</div>{error&&<div className="inline-error" role="alert">{error}</div>}<button className="primary full" disabled={busy}>{busy?'Guardando…':'Guardar cambios'}</button></form></>:modal==='delete-store' &&deleteStoreTarget?<><span className="modal-icon danger-icon"><Trash2/></span><h2>Eliminar tienda del portal</h2><p>La tienda <b>{deleteStoreTarget.name}</b> dejará de aparecer y todos sus accesos desde el portal quedarán bloqueados.</p><div className="soft-note"><Cloud size={19}/>Las carpetas y los PDF se conservan en Dropbox. Sincronizar no volverá a publicar esta tienda.</div><form onSubmit={removeStore}><label>Escribe <b>{deleteStoreTarget.name}</b> para confirmar<input required autoComplete="off" spellCheck={false} value={confirmStoreName} onChange={e=>setConfirmStoreName(e.target.value)} placeholder={deleteStoreTarget.name}/></label>{error&&<div className="inline-error" role="alert">{error}</div>}<div className="modal-actions"><button className="secondary" type="button" disabled={busy} onClick={()=>{setModal(null);setDeleteStoreTarget(null);}}>Cancelar</button><button className="primary danger-button" disabled={busy||confirmStoreName!==deleteStoreTarget.name}>{busy?'Eliminando…':'Eliminar del portal'}</button></div></form></>:modal==='store'?<><span className="modal-icon"><FolderOpen/></span><h2>Crear tienda</h2><p>Se creará una carpeta de esta tienda en tu Dropbox.</p><form onSubmit={createStore}><label>Nombre de la tienda<input required maxLength={100} value={storeName} onChange={e=>setStoreName(e.target.value)} placeholder="Ej. BRYKA Centro"/></label><div className="soft-note"><ShieldCheck size={18}/>Los lectores no tienen acceso hasta que les asignes esta tienda desde Usuarios.</div>{error&&<div className="inline-error" role="alert">{error}</div>}<button className="primary full" disabled={busy}>{busy?'Creando…':'Crear tienda'}</button></form></>:modal==='edit'&&editPerson?<><span className="modal-icon"><Pencil/></span><h2>Editar usuario</h2><p>Actualiza el nombre, el usuario de ingreso y sus permisos.</p><form onSubmit={editUser}><label>Nombre<input required maxLength={100} value={newName} onChange={e=>setNewName(e.target.value)}/></label><label>Usuario<input required pattern="[a-z0-9][a-z0-9._-]{2,39}" autoComplete="off" value={newUser} onChange={e=>setNewUser(e.target.value.toLowerCase())}/></label><label>Permisos<select value={newRole} disabled={editPerson.id===user.id} onChange={e=>setNewRole(e.target.value)}><option value="reader">Consultar, imprimir y descargar</option><option value="admin">Administrador</option></select></label>{storeChoices}{editPerson.id===user.id&&<p className="password-help">Tu cuenta conserva el permiso de administrador.</p>}{error&&<div className="inline-error" role="alert">{error}</div>}<button className="primary full" disabled={busy}>{busy?'Guardando…':'Guardar cambios'}</button></form></>:modal==='delete'&&deletePerson?<><span className="modal-icon danger-icon"><Trash2/></span><h2>Eliminar usuario</h2><p>Eliminarás el acceso de <b>{deletePerson.name}</b>. Esta acción es permanente. Los PDF de la biblioteca se conservan.</p><form onSubmit={deleteUser}><label>Escribe <b>{deletePerson.username}</b> para confirmar<input required autoComplete="off" spellCheck={false} value={confirmUsername} onChange={e=>setConfirmUsername(e.target.value)} placeholder={deletePerson.username}/></label>{error&&<div className="inline-error" role="alert">{error}</div>}<div className="modal-actions"><button className="secondary" type="button" disabled={busy} onClick={()=>{setModal(null);setDeletePerson(null);}}>Cancelar</button><button className="primary danger-button" disabled={busy||confirmUsername!==deletePerson.username}>{busy?'Eliminando…':'Eliminar acceso'}</button></div></form></>:resetPerson?<><span className="modal-icon"><KeyRound/></span><h2>Cambiar contraseña</h2><p>Asigna una nueva contraseña a <b>{resetPerson.name}</b>.</p><form onSubmit={reset}><label>Nueva contraseña<div className="password-wrap"><input type={showUserPassword?'text':'password'} autoComplete="new-password" required minLength={12} maxLength={256} value={resetPass} onChange={e=>setResetPass(e.target.value)} placeholder="Al menos 12 caracteres"/><button type="button" aria-label={showUserPassword?'Ocultar contraseña':'Mostrar contraseña'} aria-pressed={showUserPassword} onClick={()=>setShowUserPassword(v=>!v)}><Eye size={18}/></button></div></label><p className="password-help">La contraseña actual no se puede consultar. Aquí asignas una nueva.</p>{error&&<div className="inline-error">{error}</div>}<button className="primary full" disabled={busy}>{busy?'Guardando…':'Guardar contraseña'}</button></form></>:modal==='upload'?<><span className="modal-icon"><Upload/></span><h2>Subir documentos</h2><p>Los PDF se guardarán en la tienda <b>{activeStore?.name}</b>.</p><form onSubmit={upload}><input ref={input} type="file" accept="application/pdf,.pdf" multiple hidden onChange={e=>setFiles(Array.from(e.target.files||[]))}/><button className="dropzone" type="button" disabled={busy} onClick={()=>input.current?.click()} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();if(!busy)setFiles(Array.from(e.dataTransfer.files).filter(f=>f.name.toLowerCase().endsWith('.pdf')));}}><Upload size={28}/><b>{files.length?`${files.length} PDF seleccionados`:'Selecciona o arrastra tus PDF'}</b><span>{files.length?files.map(f=>f.name).join(', '):'Puedes seleccionar varios archivos a la vez'}</span></button><label>Categoría<input required maxLength={60} value={uploadCategory} onChange={e=>setUploadCategory(e.target.value)}/></label>{busy&&<div className="upload-progress"><div><i style={{width:progress+'%'}}/></div><span>{progress}% · Mantén esta ventana abierta</span></div>}{error&&<div className="inline-error">{error}</div>}<div className="soft-note"><Cloud size={19}/>Si ya están en la carpeta del portal, usa «Sincronizar Dropbox» para evitar volver a subirlos.</div><button className="primary full" disabled={busy||!files.length}>{busy?<><LoaderCircle size={17} className="spin"/>Subiendo…</>:<><Upload size={17}/>Subir y publicar</>}</button></form></>:<><span className="modal-icon"><Users/></span><h2>Nuevo usuario</h2><p>Asigna un acceso personal para consultar la biblioteca.</p><form onSubmit={addUser}><label>Nombre<input required maxLength={100} placeholder="Nombre de la persona" value={newName} onChange={e=>setNewName(e.target.value)}/></label><label>Usuario<input required pattern="[a-z0-9][a-z0-9._-]{2,39}" autoComplete="off" placeholder="coordinador.01" value={newUser} onChange={e=>setNewUser(e.target.value.toLowerCase())}/></label><label>Contraseña inicial<div className="password-wrap"><input type={showUserPassword?'text':'password'} required minLength={12} maxLength={256} autoComplete="new-password" placeholder="Al menos 12 caracteres" value={newPass} onChange={e=>setNewPass(e.target.value)}/><button type="button" aria-label={showUserPassword?'Ocultar contraseña':'Mostrar contraseña'} aria-pressed={showUserPassword} onClick={()=>setShowUserPassword(v=>!v)}><Eye size={18}/></button></div></label><label>Permisos<select value={newRole} onChange={e=>setNewRole(e.target.value)}><option value="reader">Consultar, imprimir y descargar</option><option value="admin">Administrador</option></select></label>{storeChoices}{error&&<div className="inline-error">{error}</div>}<button className="primary full" disabled={busy}>{busy?'Creando…':'Crear acceso'}<ArrowRight size={17}/></button></form></>}</section></div>}
 </div>;
}
